for (name, signature, explanation) in (
    (:FileUploadRequest, "FileUploadRequest(; filename, bytes_data=nothing, path=nothing, media_type=\"application/octet-stream\", extensions=nothing)", "Describe an upload with exactly one of nonempty bytes_data or path. The constructor does not open a path; building/submitting the upload reads it and buffers multipart content."),
    (:FileInfo, "FileInfo(; id, filename=nothing, media_type=nothing, size_bytes=nothing, created_at=nothing, expires_at=nothing, readiness=\"ready\", downloadable=nothing, provider_data=nothing)", "Describe a stored file. readiness is pending, ready or failed; missing metadata remains nothing. The object contains metadata, not downloaded bytes."),
    (:FilePage, "FilePage(; items=(), next_cursor=nothing)", "Hold FileInfo values and an optional next-page cursor. Pagination requires an explicit subsequent file_list call."),
    (:CacheInfo, "CacheInfo(; id, model, tokens=nothing, created_at=nothing, expires_at=nothing, label=nothing, provider_data=nothing)", "Describe a provider-stored prompt cache and its lifetime metadata. Construction neither creates nor refreshes a cache."),
    (:CachePage, "CachePage(; items=(), next_cursor=nothing)", "Hold CacheInfo values and an optional cursor. Fetch more pages explicitly with cache_list."),
    (:CachedPrefix, "CachedPrefix(; prefix, resource=nothing)", "Keep a generation-setting-free Request prefix and optional CacheInfo. Stored resource and prefix models must match. Use request(cached, content) to construct a follow-up; this object itself performs no network operation."),
    (:BatchRequest, "BatchRequest(; requests, model=first(requests).model, label=nothing, extensions=nothing)", "Describe a nonempty batch of Requests. If omitted, model comes from the first request. Provider restrictions on batch contents are applied when building/submitting it."),
    (:BatchJobInfo, "BatchJobInfo(; id, status, label=nothing, created_at=nothing, provider_data=nothing)", "Hold a snapshot with status queued, running, cancelling, completed, failed, cancelled or expired. Reading this value does not poll the provider."),
    (:BatchEntry, "BatchEntry(; index, outcome, response=nothing, error=nothing)", "Describe a zero-based input entry's outcome: succeeded, errored, cancelled or expired. A success has Response; an error has ErrorDetail. Do not assume output ordering alone identifies the original request."),
    (:ImageGenerationRequest, "ImageGenerationRequest(; model, prompt, size=nothing, images=(), extensions=nothing)", "Describe image generation or provider-supported editing with optional source ImageParts. Submission can incur charges; the constructor does not generate anything."),
    (:ImageGenerationResponse, "ImageGenerationResponse(; images, text=nothing, id=nothing, model=nothing, usage=Usage(), provider_data=nothing)", "Hold a nonempty tuple of generated ImageParts and optional accompanying text/metadata. Inspect whether each image is inline or a URL before calling bytes."),
    (:SpeechGenerationRequest, "SpeechGenerationRequest(; model, prompt, voice=nothing, format=nothing, extensions=nothing)", "Describe speech synthesis. Supported voices and formats belong to the selected provider/model. Construction performs no generation."),
    (:SpeechGenerationResponse, "SpeechGenerationResponse(; audio, id=nothing, model=nothing, usage=Usage(), provider_data=nothing)", "Hold a generated AudioPart and optional metadata. bytes(response.audio) reads inline/local content; fetching remote URLs is explicit."),
    (:VideoGenerationRequest, "VideoGenerationRequest(; model, prompt, seconds=nothing, images=(), extensions=nothing)", "Describe an asynchronous video job. seconds, if given, must be positive. Inputs and duration remain subject to provider limits."),
    (:VideoJobInfo, "VideoJobInfo(; id, status, progress=nothing, created_at=nothing, model=nothing, provider_data=nothing)", "Hold video status queued, running, completed, failed or cancelled. progress, when reported, is between zero and 100. No polling occurs when reading the snapshot."),
    (:BatchJob, "BatchJob(client, info::BatchJobInfo)", "Own a mutable batch handle with lm and info fields. Prefer batch to submit or batch_job to attach. refresh! and wait! update info; done reads only the current snapshot."),
    (:VideoJob, "VideoJob(client, info::VideoJobInfo)", "Own a mutable video-job handle. Prefer video_generate or video_job. Reading info does not poll; result explicitly fetches output and does not wait for completion."),
    (:WaitTimeout, "WaitTimeout(snapshot)", "Report that a polling deadline elapsed. snapshot is the last known FileInfo or job-info value. The remote operation can still be running and billing; this is not cancellation."),
    (:file_upload, "file_upload(client, request::FileUploadRequest)", "Upload a file and return FileInfo. Reads local paths and buffers the upload; contacts the provider and can create billable storage. See file_wait_ready before relying on asynchronous processing."),
    (:file_get, "file_get(client, id)", "Fetch one FileInfo snapshot from the provider. This contacts the provider but does not download file content."),
    (:file_list, "file_list(client; limit=20, cursor=nothing)", "Fetch one FilePage. Follow next_cursor explicitly. Provider limits may further restrict page size."),
    (:file_delete, "file_delete(client, id)", "Delete a provider file and return nothing. This changes remote state; no implicit retry is performed."),
    (:file_download, "file_download(client, id)", "Download provider file content as a byte vector. Materializes the full response in memory; provider support and permissions are required."),
    (:file_wait_ready, "file_wait_ready(client, id; poll_every=2.0, timeout=nothing)", "Poll until file readiness is no longer pending; return the final FileInfo, which can be failed rather than ready. Positive poll intervals and nonnegative optional timeouts are in seconds. A deadline does not interrupt a request already in flight."),
    (:cache_create, "cache_create(client, prefix::Request; ttl_seconds=nothing, label=nothing)", "Create a provider-stored cache and return CacheInfo. The prefix must not contain generation settings; a supplied TTL must be positive. Contacts the provider and may incur charges."),
    (:cache_get, "cache_get(client, id)", "Fetch CacheInfo from the provider. Does not extend the cache's lifetime."),
    (:cache_list, "cache_list(client; limit=20, cursor=nothing)", "Fetch one CachePage. Further pages require another explicit call."),
    (:cache_delete, "cache_delete(client, id)", "Delete a provider-stored cache and return nothing. Existing cached-prefix handles may then refer to an unavailable resource."),
    (:cache_update, "cache_update(client, id; ttl_seconds)", "Update a stored cache's positive lifetime and return CacheInfo. Requires provider support; contacts the provider."),
    (:cache, "cache(client_or_router, prefix::Request; ttl_seconds=nothing, label=nothing)", "Prepare a CachedPrefix. Gemini's stored-cache path creates a remote resource; other supported implicit-cache paths retain a local prefix. This function is therefore not universally offline. The prefix must not carry generation settings."),
    (:cache_config, "cache_config(cached::CachedPrefix)", "Return CacheConfig pointing at a stored resource or defining an implicit prefix boundary. This is local and creates no resource."),
    (:request, "request(cached::CachedPrefix, messages; config=nothing)", "Build a Request combining the canonical prefix and a nonempty suffix. Accept text, a Message, a sequence of Messages, or a suffix Request with the same model and no system/tools. A suffix Request supplies its config unless overridden; config.cache is owned by CachedPrefix and must not already be set. The canonical prefix stays in the Request; a supported stored-cache mapping can avoid resending it on the wire. No request is submitted."),
    (:image_generate, "image_generate(client, request::ImageGenerationRequest)", "Submit image generation and return ImageGenerationResponse. Contacts a provider and can incur charges; materialized images use memory. Unsupported editing/input forms are refused."),
    (:speech_generate, "speech_generate(client, request::SpeechGenerationRequest)", "Submit speech synthesis and return SpeechGenerationResponse. Contacts the provider, can incur charges, and buffers returned audio."),
    (:batch_submit, "batch_submit(client, request::BatchRequest)", "Submit a remote batch and return BatchJobInfo. Some providers first require a file upload, so one high-level submission may make more than one request. There are no automatic retries."),
    (:batch_status, "batch_status(client, id)", "Fetch a BatchJobInfo snapshot. This polls once; it does not wait for terminal status."),
    (:batch_results, "batch_results(client, id)", "Fetch and parse batch outputs as BatchEntry values. May require additional provider file downloads. Does not wait for the job to finish; inspect status first."),
    (:batch_cancel, "batch_cancel(client, id)", "Request remote batch cancellation and return BatchJobInfo. Cancellation can be pending and does not imply all billing stops."),
    (:batch_list, "batch_list(client; limit=20)", "Fetch available BatchJobInfo snapshots from the provider. No implicit polling or pagination loop is performed."),
    (:batch, "batch(client, requests; kwargs...)", "Submit a BatchRequest or collection of Requests and return BatchJob. Extra keywords configure BatchRequest. Submission is explicit, remote and potentially billable."),
    (:batch_job, "batch_job(client, id)", "Fetch current batch status and return a BatchJob handle for that existing ID. Does not submit a replacement job."),
    (:batches, "batches(client; limit=20)", "List BatchJob handles from provider status snapshots. Reading the returned handles does not refresh them."),
    (:video_submit, "video_submit(client, request::VideoGenerationRequest)", "Submit video generation and return VideoJobInfo. Provider-specific multi-step submissions may make multiple requests; the job may continue after the call returns."),
    (:video_status, "video_status(client, id)", "Fetch one VideoJobInfo snapshot. Does not wait or cancel the job."),
    (:video_list, "video_list(client; limit=20, model=nothing)", "List VideoJobInfo values where supported. Some providers, including the declared xAI path, explicitly refuse video listing."),
    (:video_result, "video_result(client, id)", "Fetch a generated VideoPart, including required provider downloads. Does not wait for completion and can buffer substantial media."),
    (:video_generate, "video_generate(client, request::VideoGenerationRequest)", "Submit video generation and return a VideoJob. Use wait! followed by result; a wait timeout leaves remote work running."),
    (:video_job, "video_job(client, id)", "Fetch status for an existing video ID and return VideoJob. Does not submit a new video."),
    (:video_jobs, "video_jobs(client; limit=20, model=nothing)", "List VideoJob handles for providers that support listing. No generic video cancel! operation is supplied."),
    (:done, "done(info_or_job)", "Return whether the current batch/video snapshot is terminal. Completed, failed, cancelled and (for batches) expired are terminal. This is a local observation, not a fresh provider check or proof of success."),
    (:refresh!, "refresh!(job::Union{BatchJob,VideoJob})", "Fetch one status snapshot, mutate job.info, and return the same job. Contacts the provider."),
    (:wait!, "wait!(job; poll_every=job isa BatchJob ? 30.0 : 5.0, timeout=nothing)", "Poll and update a batch/video job until terminal, returning the same handle. A terminal job returns immediately. The deadline bounds the polling loop, not an HTTP call already in progress; WaitTimeout carries the latest info. No retry, resubmission or automatic cancellation occurs. Check job.info.status before using output."),
    (:cancel!, "cancel!(job::BatchJob)", "Request batch cancellation, replace job.info with the returned snapshot, and return the handle. There is no corresponding generic VideoJob method; cancellation and billing behavior remain provider-specific."),
    (:results, "results(job::BatchJob)", "Fetch BatchEntry outputs. This contacts the provider and may download files. It does not call wait! implicitly."),
    (:result, "result(job::VideoJob)\n    result(view::TurnView)", "For a video job, fetch a VideoPart without implicit waiting. For a live TurnView, consume events until a turn boundary or a tool call and return Turn; a tool call deliberately returns control to your application. These operations perform network I/O through their respective clients/sessions."),
)
    doc = "    " * signature * "\n\n" * explanation
    @eval @doc $doc $name
end
